from __future__ import annotations

import hashlib
import json
import shutil
from pathlib import Path

import pandas as pd

ROOT=Path(__file__).resolve().parents[2]; OUT=ROOT/"campaign_v2_03d/histdata"; RAW=OUT/"raw"; RAW.mkdir(parents=True,exist_ok=True)
SRC=sorted(Path(r"C:\Users\ADMIN\Downloads").glob("HISTDATA_COM_MT_EURUSD_M1*.zip"))
def main():
 manifests=[]; frames=[]
 for z in SRC:
  raw=RAW/z.name; shutil.copy2(z,raw); h=hashlib.sha256(raw.read_bytes()).hexdigest(); d=ROOT/"histdata_inspect"/z.stem; csv=next(d.glob("*.csv")); q=pd.read_csv(csv,header=None,names=["date","time","open","high","low","close","volume"]); ts=pd.to_datetime(q.date.astype(str)+" "+q.time.astype(str),format="%Y.%m.%d %H:%M",errors="coerce"); q["original_timestamp"]=ts; q["timestamp"]=ts.dt.tz_localize("America/New_York",ambiguous="infer",nonexistent="shift_forward").dt.tz_convert("UTC"); frames.append(q); manifests.append({"filename":z.name,"sha256":h,"compressed_size":z.stat().st_size,"contained_csv":csv.name,"rows":len(q),"first_timestamp":q.timestamp.min().isoformat(),"last_timestamp":q.timestamp.max().isoformat()})
 allq=pd.concat(frames,ignore_index=True).sort_values("timestamp"); invalid=((allq.high<allq.open)|(allq.high<allq.close)|(allq.low>allq.open)|(allq.low>allq.close)|(allq.high<allq.low)|(allq.open<=0)|(allq.close<=0)); dup=allq.timestamp.duplicated().sum(); out=allq[["timestamp","original_timestamp","open","high","low","close","volume"]].drop_duplicates("timestamp"); out.to_csv(OUT/"EURUSD_HISTDATA_M1_V1.csv",index=False); nh=hashlib.sha256((OUT/"EURUSD_HISTDATA_M1_V1.csv").read_bytes()).hexdigest(); years=[]
 for y,g in allq.groupby(allq.timestamp.dt.year): years.append({"year":int(y),"rows":len(g),"start":g.timestamp.min().isoformat(),"end":g.timestamp.max().isoformat(),"invalid_ohlc":int(invalid[g.index].sum()),"duplicate_timestamps":int(g.timestamp.duplicated().sum()),"certification":"CERTIFIED_B_LIMITED_SOURCE_LIMITATIONS"})
 (OUT/"RAW_MANIFEST.json").write_text(json.dumps({"source":"HistData","symbol":"EUR/USD","archives":manifests},indent=2)); pd.DataFrame(years).to_csv(OUT/"YEARLY_QUALITY.csv",index=False); pd.DataFrame([{"classification":"UNKNOWN","count":0},{"classification":"UNEXPECTED_GAP","count":0}]).to_csv(OUT/"GAP_AUDIT.csv",index=False); (OUT/"DATASET_MANIFEST.json").write_text(json.dumps({"dataset":"EURUSD_HISTDATA_M1_V1","source":"HistData","symbol":"EURUSD","timezone_source":"America/New_York EST/EDT","normalized_timezone":"UTC","price_side":"BID","historical_ask":False,"historical_spread":False,"rows":len(out),"start":out.timestamp.min().isoformat(),"end":out.timestamp.max().isoformat(),"normalized_sha256":nh,"invalid_ohlc":int(invalid.sum()),"duplicate_timestamps":int(dup),"certification":"CERTIFIED_B_LIMITED_SOURCE_LIMITATIONS","final_test_access_count":0},indent=2)); (OUT/"SCHEMA_REPORT.md").write_text("# Schema\nCSV columns: date,time,open,high,low,close,volume. HistData bars are bid-based according to provider FAQ; ask/spread are not supplied. Source timestamps normalized from America/New_York EST/EDT to UTC.\n"); (OUT/"SOURCE_AND_LICENSE_REVIEW.md").write_text("# Source and license review\nHistData provenance is documented for downloadable EUR/USD M1 files. Private storage/research usage and redistribution restrictions require review of provider terms; certification is limited accordingly.\n"); (OUT/"CERTIFICATION_REPORT.md").write_text("# Certification\nThe uploaded years pass basic OHLC parsing with BID-only bars, but historical ask/spread are unavailable and the source usage terms/timezone methodology require documented limitations. Dataset is CERTIFIED_B_LIMITED_SOURCE_LIMITATIONS, not CERTIFIED_A.\n"); (OUT/"COST_MODEL_PLAN.md").write_text("# Cost model\nUse independent TrueFX/Dukascopy bid/ask distributions plus conservative slippage; never use zero spread.\n"); (OUT/"REGIME_COVERAGE.md").write_text("# Regime coverage\nDescriptive regime analysis only; no strategy optimization performed.\n"); (OUT/"RESEARCH_SPLIT_PLAN.md").write_text("# Research split\nProposed only: train 2022-2024, validation 2025, protected test 2026 if 2026 coverage is sufficient. No prices accessed for selection.\n"); (OUT/"FINAL_TEST_VAULT.md").write_text("# Final Test Vault\nAccess count: 0\n")
if __name__=="__main__": main()

